import * as React from "react";

// Redeclare forwardRef
// solve issues with component using forwardRef that loose their props typings
// @see https://fettblog.eu/typescript-react-generic-forward-refs/#option-3%3A-augment-forwardref
declare module "react" {
  function forwardRef<T, P = {}>(
    render: (props: P, ref: React.Ref<T>) => JSX.Element | null
  ): (props: P & React.RefAttributes<T>) => JSX.Element | null;
}